def localize_acg_error(message: str, lang: str) -> tuple[str, str]:
    """Return a stable public error code and locale-specific display text."""
    text = str(message or "")
    checks = (
        ("yaml_required", ("占術YAMLを貼り付け",)),
        ("yaml_too_large", ("YAMLテキストが大きすぎ",)),
        ("yaml_parse", ("YAMLを解析できません", "解析できませんでした")),
        ("yaml_ambiguous", ("複数見つかりました",)),
        ("yaml_missing_birth", ("出生日時データが見つかりません",)),
        ("birth_time", ("正確な出生時刻が必要", "出生時刻が不明", "出生時刻が必要")),
        ("timezone", ("タイムゾーンを確認できません",)),
        ("birth_place", ("出生地を確認できません",)),
        ("date_format", ("日付は YYYY-MM-DD", "input.birth_date は YYYY-MM-DD")),
        ("date_range", ("年の範囲",)),
        ("time_format", ("HH:MM 形式",)),
        ("time_range", ("時刻が有効範囲外",)),
        ("timezone_offset", ("timezone_offset_hours",)),
    )
    code = next((key for key, needles in checks if any(needle in text for needle in needles)), "input_invalid")
    locale = lang if lang in ACG_ERROR_UI else "ja"
    return code, ACG_ERROR_UI[locale][code]
